# openEMS model generated by OpenBoard (RF PCB). Requires openEMS + CSXCAD Python bindings.
import os, numpy as np
from CSXCAD import ContinuousStructure
from openEMS import openEMS
from openEMS.physical_constants import C0
unit = 1e-3; f_max = 10e9; f0 = f_max / 2; fc = f_max / 2
FDTD = openEMS(NrTS=60000, EndCriteria=1e-4)
FDTD.SetGaussExcite(f0, fc)
FDTD.SetBoundaryCond(['PML_8'] * 6)
CSX = ContinuousStructure()
FDTD.SetCSX(CSX)
mesh = CSX.GetGrid(); mesh.SetDeltaUnit(unit)
metal = CSX.AddMetal("copper")
sub0 = CSX.AddMaterial("diel0", epsilon=4.4, kappa=2.4478e-2)
sub0.AddBox([0, 0, 0.035], [46.6, 49.4, 1.565], priority=0)
metal.AddLinPoly(points=np.array([[17.3, 29.3, 29.3, 25.3, 25.3, 43.6, 43.6, 21.3, 21.3, 17.3], [46.4, 46.4, 34.8, 9.8, 8.8, 8.8, 3, 3, 9.8, 34.8]]), norm_dir='z', elevation=0, length=0.035, priority=10)  # 0
metal.AddLinPoly(points=np.array([[21.895, 24.705, 24.705, 25.3, 25.3, 3, 3, 21.3, 21.3, 21.895], [44.2, 44.2, 34.8, 9.8, 3, 3, 8.8, 8.8, 9.8, 34.8]]), norm_dir='z', elevation=1.565, length=0.035, priority=10)  # 1
metal.AddLinPoly(points=np.array([[25.705, 29.3, 29.3, 25.705], [46.4, 46.4, 39.8, 39.8]]), norm_dir='z', elevation=1.565, length=0.035, priority=10)  # 2
metal.AddLinPoly(points=np.array([[17.3, 20.895, 20.895, 17.3], [46.4, 46.4, 39.8, 39.8]]), norm_dir='z', elevation=1.565, length=0.035, priority=10)  # 3
metal.AddLinPoly(points=np.array([[21.7, 24.9, 24.9, 21.7], [43.565, 43.565, 44.835, 44.835]]), norm_dir='z', elevation=1.565, length=0.035, priority=10)  # 4
metal.AddLinPoly(points=np.array([[24.275, 27.975, 27.975, 24.275], [43.775, 43.775, 45.125, 45.125]]), norm_dir='z', elevation=1.565, length=0.035, priority=10)  # 5
metal.AddLinPoly(points=np.array([[24.275, 27.975, 27.975, 24.275], [43.775, 43.775, 45.125, 45.125]]), norm_dir='z', elevation=1.565, length=0.035, priority=10)  # 6
metal.AddLinPoly(points=np.array([[18.625, 22.325, 22.325, 18.625], [43.775, 43.775, 45.125, 45.125]]), norm_dir='z', elevation=1.565, length=0.035, priority=10)  # 7
metal.AddLinPoly(points=np.array([[18.625, 22.325, 22.325, 18.625], [43.775, 43.775, 45.125, 45.125]]), norm_dir='z', elevation=1.565, length=0.035, priority=10)  # 8
metal.AddLinPoly(points=np.array([[24.275, 27.975, 27.975, 24.275], [43.775, 43.775, 45.125, 45.125]]), norm_dir='z', elevation=0, length=0.035, priority=10)  # 9
metal.AddLinPoly(points=np.array([[18.625, 22.325, 22.325, 18.625], [43.775, 43.775, 45.125, 45.125]]), norm_dir='z', elevation=0, length=0.035, priority=10)  # 10
port1 = FDTD.AddLumpedPort(1, 50, [22.665, 43.565, 0.035], [23.935, 44.835, 1.565], 'z', excite=1, priority=20)  # J1-1
mesh.AddLine('x', [0, 46.6]); mesh.AddLine('y', [0, 49.4]); mesh.AddLine('z', [-3, 4.6])
mesh.AddLine('z', [1.565, 1.6, 0, 0.035])
for d in 'xyz':
    mesh.SmoothMeshLines(d, C0 / f_max / unit / 20, 1.4)
sim = os.path.join(os.getcwd(), 'openboard_rf')
FDTD.Run(sim, cleanup=True)
f = np.linspace(max(1e6, f0 - fc), f0 + fc, 401)
for prt in [p for p in [globals().get("port%d" % i) for i in range(1, 9)] if p is not None]: prt.CalcPort(sim, f)
s11 = port1.uf_ref / port1.uf_inc
out = ["# Hz S RI R 50"] + ["%g %g %g" % (fi, s.real, s.imag) for fi, s in zip(f, s11)]
if 'port2' in globals(): s21 = port2.uf_ref / port1.uf_inc; out = ["# Hz S RI R 50"] + ["%g %g %g %g %g %g %g %g %g" % (fi, a.real, a.imag, b.real, b.imag, b.real, b.imag, a.real, a.imag) for fi, a, b in zip(f, s11, s21)]
open('openboard_rf.s%dp' % (2 if 'port2' in globals() else 1), 'w').write('\n'.join(out))
